 run:function(){
   if(typeof drawOp!=='function') return 'SKIP: no painter here';
   var bad=[], w0=wc, cvs=document.createElement('canvas'), x2, n=0, oF, oFR, gt=null;
   cvs.width=240; cvs.height=160; x2=cvs.getContext('2d'); if(!x2) return 'SKIP: no canvas';
   function base(o){ var b={hero:0,moving:false,sprint:false,ads:false,hurt:0,rl:0,bulk:0,skin:'fair',own:{wep:null}}, k; for(k in o) b[k]=o[k]; return b; }
   function paint(st,face){ n=0; x2.setTransform(1,0,0,1,0,0); x2.clearRect(0,0,240,160); x2.setTransform(4,0,0,4,120,130); wc=x2;
     try{ drawOp(0,0,face||0,0,'#242832',0,0,'down',0,st); } finally { wc=w0; x2.setTransform(1,0,0,1,0,0); }
     return x2.getImageData(0,0,240,160).data; }
   function depth(d,lx){ var cx=Math.round(120+lx*4), y, t=-1, b=-1; for(y=0;y<160;y++){ if(d[(y*240+cx)*4+3]>200){ if(t<0) t=y; b=y; } } return t<0?0:(b-t+1)/4; }
   function mass(d){ var sx=0, c=0, i; for(i=0;i<d.length;i+=4) if(d[i+3]>200){ sx+=(i/4)%240; c++; } return c?sx/c:0; }
   try{
     oF=x2.fill; oFR=x2.fillRect;
